import bisect

class Solution:
    def maximumCount(self, nums: list[int]) -> int:
        neg = bisect.bisect_left(nums, 0)
        pos = len(nums) - bisect.bisect_right(nums, 0)
        return max(neg, pos)

class Solution {
public:
    int maximumCount(std::vector<int>& nums) {
        auto it_neg = std::lower_bound(nums.begin(), nums.end(), 0);
        auto it_pos = std::upper_bound(nums.begin(), nums.end(), 0);
        int neg = it_neg - nums.begin();
        int pos = nums.end() - it_pos;
        return std::max(neg, pos);
    }
};

class Solution {
    public int maximumCount(int[] nums) {
        int n = nums.length;
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] < 0) lo = mid + 1;
            else hi = mid;
        }
        int neg = lo;
        lo = 0; hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] <= 0) lo = mid + 1;
            else hi = mid;
        }
        int pos = n - lo;
        return Math.max(neg, pos);
    }
}

var maximumCount = function(nums) {
    const n = nums.length;
    let lo = 0, hi = n;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (nums[mid] < 0) lo = mid + 1;
        else hi = mid;
    }
    const neg = lo;
    lo = 0; hi = n;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (nums[mid] <= 0) lo = mid + 1;
        else hi = mid;
    }
    const pos = n - lo;
    return Math.max(neg, pos);
};
